def data(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            v = (i * 7919 + j * 104729 + i * j * 13 + j * j * 3) % 101
            X[i, j] = (v - 50.0) / 25.0 + (0.8 * y[i] if (j + y[i]) % 2 == 0 else -0.3 * y[i])
    return X, y

def counts(n: int, p: int, nc: int):
    X = np.zeros((n, p)); y = np.zeros(n, dtype=int)
    for i in range(n):
        y[i] = i % nc
        for j in range(p):
            X[i, j] = float((i * 31 + j * 17 + i * j * 7 + y[i] * (j + 1)) % 6)
    return X, y

def close(got, exp: List[float], rtol: float = 1e-9, atol: float = 1e-12) -> bool:
    g = np.asarray(got, dtype=float).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if np.isnan(exp[i]):
            if not np.isnan(g[i]):
                print("mismatch at", i, g[i], exp[i])
                return False
            continue
        if abs(g[i] - exp[i]) > atol + rtol * abs(exp[i]):
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

def eqi(got, exp: List[int]) -> bool:
    g = np.asarray(got).ravel()
    if g.size != len(exp):
        print("size mismatch", g.size, len(exp))
        return False
    for i in range(len(exp)):
        if int(g[i]) != exp[i]:
            print("mismatch at", i, g[i], exp[i])
            return False
    return True

failed = 0
def check(ok: bool, name: str):
    global failed
    if not ok:
        print("TEST FAILED:", name)
        failed += 1

X, y = data(60, 4, 3)
Q = X[:7] + 0.13

g = GaussianNB().fit(X, y)
check(close(g.theta_, gnb_theta), "gnb theta")
check(close(g.var_, gnb_var), "gnb var")
check(close(g.class_prior_, gnb_prior), "gnb prior")
check(close([g.epsilon_], [gnb_eps]), "gnb eps")
check(close(g.predict_proba(Q), gnb_proba, 1e-7, 1e-300), "gnb proba")
check(close(g.predict_log_proba(Q), gnb_logp, 1e-8, 1e-9), "gnb logp")
check(eqi(g.predict(X), gnb_pred), "gnb pred")
g2 = GaussianNB(priors=[0.2, 0.3, 0.5], var_smoothing=1e-3)
g2.partial_fit(X[:25], y[:25], classes=[0, 1, 2])
g2.partial_fit(X[25:], y[25:])
check(close(g2.theta_, gnb_pf_theta), "gnb pf theta")
check(close(g2.var_, gnb_pf_var), "gnb pf var")
check(close(g2.predict_proba(Q), gnb_pf_proba, 1e-7, 1e-300), "gnb pf proba")
sw = np.empty(60)
for t in range(60):
    sw[t] = float(t % 5) + 1.0
g3 = GaussianNB().fit(X, y, sample_weight=sw)
check(close(g3.theta_, gnb_sw_theta), "gnb sw theta")
check(close(g3.var_, gnb_sw_var), "gnb sw var")
check(close(cross_val_score(GaussianNB(), X, y), cvs_gnb), "gnb cv")

C, yc = counts(50, 6, 3)
Cq = np.ascontiguousarray(C[:6][::-1] + 1.0)
Cr = np.ascontiguousarray(C[:6][::-1])
m = MultinomialNB(alpha=0.5).fit(C, yc)
check(close(m.feature_log_prob_, mnb_flp), "mnb flp")
check(close(m.class_log_prior_, mnb_clp), "mnb clp")
check(close(m.predict_proba(Cq), mnb_proba, 1e-8, 1e-300), "mnb proba")
check(eqi(m.predict(C), mnb_pred), "mnb pred")
m2 = MultinomialNB(fit_prior=False)
m2.partial_fit(C[:20], yc[:20], classes=[0, 1, 2])
m2.partial_fit(C[20:], yc[20:], sample_weight=sw[:30])
check(close(m2.feature_log_prob_, mnb_pf_flp), "mnb pf flp")
check(close(m2.predict_proba(Cq), mnb_pf_proba, 1e-8, 1e-300), "mnb pf proba")
cn = ComplementNB().fit(C, yc)
check(close(cn.feature_log_prob_, cnb_flp), "cnb flp")
check(close(cn.predict_proba(Cq), cnb_proba, 1e-8, 1e-300), "cnb proba")
check(eqi(cn.predict(C), cnb_pred), "cnb pred")
cn2 = ComplementNB(norm=True, alpha=0.3).fit(C, yc)
check(close(cn2.feature_log_prob_, cnb_norm_flp), "cnb norm flp")
check(eqi(cn2.predict(Cq), cnb_norm_pred), "cnb norm pred")
b = BernoulliNB(binarize=2.0).fit(C, yc)
check(close(b.feature_log_prob_, bnb_flp), "bnb flp")
check(close(b.predict_proba(Cq), bnb_proba, 1e-8, 1e-300), "bnb proba")
check(eqi(b.predict(C), bnb_pred), "bnb pred")
ca = CategoricalNB(alpha=0.7).fit(C, yc)
check(close(ca.predict_proba(Cr), catnb_proba, 1e-8, 1e-300), "catnb proba")
check(eqi(ca.predict(C), catnb_pred), "catnb pred")
check(eqi(ca.n_categories_, catnb_ncat), "catnb ncat")
check(close(ca.feature_log_prob_[0], catnb_flp0), "catnb flp0")

pipe = make_pipeline(StandardScaler(), GaussianNB())
pipe.fit(X, y)
Xs = StandardScaler().fit_transform(X)
ref = GaussianNB().fit(Xs, y).predict(Xs)
pp = pipe.predict(X)
ok = pp.shape[0] == ref.shape[0]
for t in range(ref.shape[0]):
    if int(pp[t]) != int(ref[t]):
        ok = False
check(ok, "pipeline gnb")
gc = clone(g)
check(gc.var_smoothing == 1e-9, "clone")

if failed:
    print("TEST FAILED", failed)
    sys.exit(1)
